/* 从 NOR/SRAM 用法切换到 NAND 用法前，先清掉 Bank1 的残留配置 */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_FSMC, ENABLE);
FSMC_NORSRAMDeInit(FSMC_Bank1_NORSRAM1);

/* 此后可以安全地用 FSMC_NANDInit 配置 Bank2 */

/* 换用另一种 NAND（页大小、时序都不同）前先复位配置 */
FSMC_NANDDeInit(FSMC_Bank2_NAND);

/* 再按新芯片的参数重新初始化 */
FSMC_NANDInit(&FSMC_NANDInitStructure);
FSMC_NANDCmd(FSMC_Bank2_NAND, ENABLE);

/* PC Card 只有 Bank4 一个，所以本函数没有 Bank 参数 */
FSMC_PCCARDDeInit();
FSMC_PCCARDInit(&FSMC_PCCARDInitStructure);
FSMC_PCCARDCmd(ENABLE);

FSMC_NORSRAMInitTypeDef  FSMC_NORSRAMInitStructure;
FSMC_NORSRAMTimingInitTypeDef  ReadWriteTiming;

/* 1. 开 FSMC 时钟（AHB 外设） */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_FSMC, ENABLE);

/* 2. 时序：HCLK=72MHz，1 个 HCLK 约 13.9ns */
ReadWriteTiming.FSMC_AddressSetupTime      = 0x01;  /* 地址建立 2 HCLK  */
ReadWriteTiming.FSMC_AddressHoldTime       = 0x00;
ReadWriteTiming.FSMC_DataSetupTime         = 0x05;  /* 数据建立 6 HCLK  */
ReadWriteTiming.FSMC_BusTurnAroundDuration = 0x00;
ReadWriteTiming.FSMC_CLKDivision           = 0x00;
ReadWriteTiming.FSMC_DataLatency           = 0x00;
ReadWriteTiming.FSMC_AccessMode            = FSMC_AccessMode_A;  /* SRAM 固定用模式 A */

/* 3. 存储块配置：Bank1 的 NORSRAM3（对应地址 0x68000000） */
FSMC_NORSRAMInitStructure.FSMC_Bank                = FSMC_Bank1_NORSRAM3;
FSMC_NORSRAMInitStructure.FSMC_DataAddressMux      = FSMC_DataAddressMux_Disable;
FSMC_NORSRAMInitStructure.FSMC_MemoryType          = FSMC_MemoryType_SRAM;
FSMC_NORSRAMInitStructure.FSMC_MemoryDataWidth     = FSMC_MemoryDataWidth_16b;
FSMC_NORSRAMInitStructure.FSMC_BurstAccessMode     = FSMC_BurstAccessMode_Disable;
FSMC_NORSRAMInitStructure.FSMC_AsynchronousWait    = FSMC_AsynchronousWait_Disable;
FSMC_NORSRAMInitStructure.FSMC_WaitSignalPolarity  = FSMC_WaitSignalPolarity_Low;
FSMC_NORSRAMInitStructure.FSMC_WrapMode            = FSMC_WrapMode_Disable;
FSMC_NORSRAMInitStructure.FSMC_WaitSignalActive    = FSMC_WaitSignalActive_BeforeWaitState;
FSMC_NORSRAMInitStructure.FSMC_WriteOperation      = FSMC_WriteOperation_Enable;
FSMC_NORSRAMInitStructure.FSMC_WaitSignal          = FSMC_WaitSignal_Disable;
FSMC_NORSRAMInitStructure.FSMC_ExtendedMode        = FSMC_ExtendedMode_Disable;
FSMC_NORSRAMInitStructure.FSMC_WriteBurst          = FSMC_WriteBurst_Disable;
FSMC_NORSRAMInitStructure.FSMC_ReadWriteTimingStruct = &ReadWriteTiming;
FSMC_NORSRAMInitStructure.FSMC_WriteTimingStruct     = &ReadWriteTiming;
FSMC_NORSRAMInit(&FSMC_NORSRAMInitStructure);

/* 4. 使能该 Bank */
FSMC_NORSRAMCmd(FSMC_Bank1_NORSRAM3, ENABLE);

/* 5. 之后就能像访问内存一样读写外部 SRAM */
*(volatile uint16_t*)0x68000000 = 0x1234;

FSMC_NANDInitTypeDef  FSMC_NANDInitStructure;
FSMC_NAND_PCCARDTimingInitTypeDef  ComSpaceTiming, AttSpaceTiming;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_FSMC, ENABLE);

/* 公共区时序：HCLK=72MHz，1 周期约 13.9ns */
ComSpaceTiming.FSMC_SetupTime      = 0x01;  /* tCLR/tAR */
ComSpaceTiming.FSMC_WaitSetupTime  = 0x03;  /* tWP >= 25ns */
ComSpaceTiming.FSMC_HoldSetupTime  = 0x02;  /* tRP */
ComSpaceTiming.FSMC_HiZSetupTime   = 0x01;
AttSpaceTiming = ComSpaceTiming;

FSMC_NANDInitStructure.FSMC_Bank                  = FSMC_Bank2_NAND;
FSMC_NANDInitStructure.FSMC_Waitfeature           = FSMC_Waitfeature_Enable;  /* 用 R/B 做握手 */
FSMC_NANDInitStructure.FSMC_MemoryDataWidth       = FSMC_MemoryDataWidth_8b;
FSMC_NANDInitStructure.FSMC_ECC                   = FSMC_ECC_Enable;
FSMC_NANDInitStructure.FSMC_ECCPageSize           = FSMC_ECCPageSize_2048Bytes;
FSMC_NANDInitStructure.FSMC_TCLRSetupTime         = 0x00;
FSMC_NANDInitStructure.FSMC_TARSetupTime          = 0x00;
FSMC_NANDInitStructure.FSMC_CommonSpaceTimingStruct    = &ComSpaceTiming;
FSMC_NANDInitStructure.FSMC_AttributeSpaceTimingStruct = &AttSpaceTiming;
FSMC_NANDInitStructure.FSMC_IOSpaceTimingStruct        = &AttSpaceTiming;
FSMC_NANDInit(&FSMC_NANDInitStructure);
FSMC_NANDCmd(FSMC_Bank2_NAND, ENABLE);

FSMC_PCCARDInitTypeDef  FSMC_PCCARDInitStructure;
FSMC_NAND_PCCARDTimingInitTypeDef  Timing;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_FSMC, ENABLE);

Timing.FSMC_SetupTime     = 0x04;
Timing.FSMC_WaitSetupTime = 0x06;
Timing.FSMC_HoldSetupTime = 0x04;
Timing.FSMC_HiZSetupTime  = 0x02;

FSMC_PCCARDInitStructure.FSMC_CommonSpaceTimingStruct    = &Timing;
FSMC_PCCARDInitStructure.FSMC_AttributeSpaceTimingStruct = &Timing;
FSMC_PCCARDInitStructure.FSMC_IOSpaceTimingStruct        = &Timing;
FSMC_PCCARDInit(&FSMC_PCCARDInitStructure);
FSMC_PCCARDCmd(ENABLE);

FSMC_NORSRAMInitTypeDef FSMC_NORSRAMInitStructure;
FSMC_NORSRAMTimingInitTypeDef ReadWriteTiming;

/* 先填默认值，避免结构体里是随机数 */
FSMC_NORSRAMStructInit(&FSMC_NORSRAMInitStructure);

/* 再改需要改的字段（默认是 Bank1_NORSRAM1 + SRAM + 16b） */
FSMC_NORSRAMInitStructure.FSMC_Bank = FSMC_Bank1_NORSRAM3;

/* 时序结构一定要自己定义并显式挂上去 */
ReadWriteTiming.FSMC_AddressSetupTime      = 0x01;
ReadWriteTiming.FSMC_DataSetupTime         = 0x05;
ReadWriteTiming.FSMC_AccessMode            = FSMC_AccessMode_A;
FSMC_NORSRAMInitStructure.FSMC_ReadWriteTimingStruct = &ReadWriteTiming;
FSMC_NORSRAMInitStructure.FSMC_WriteTimingStruct     = &ReadWriteTiming;
FSMC_NORSRAMInit(&FSMC_NORSRAMInitStructure);

FSMC_NANDInitTypeDef FSMC_NANDInitStructure;
FSMC_NAND_PCCARDTimingInitTypeDef ComSpaceTiming;

FSMC_NANDStructInit(&FSMC_NANDInitStructure);   /* 默认 Bank2_NAND、8b、ECC 关闭 */

FSMC_NANDInitStructure.FSMC_ECC         = FSMC_ECC_Enable;
FSMC_NANDInitStructure.FSMC_ECCPageSize = FSMC_ECCPageSize_2048Bytes;

ComSpaceTiming.FSMC_SetupTime     = 0x01;
ComSpaceTiming.FSMC_WaitSetupTime = 0x03;
ComSpaceTiming.FSMC_HoldSetupTime = 0x02;
ComSpaceTiming.FSMC_HiZSetupTime  = 0x01;
FSMC_NANDInitStructure.FSMC_CommonSpaceTimingStruct = &ComSpaceTiming;
FSMC_NANDInit(&FSMC_NANDInitStructure);

FSMC_PCCARDInitTypeDef FSMC_PCCARDInitStructure;
FSMC_NAND_PCCARDTimingInitTypeDef Timing;

FSMC_PCCARDStructInit(&FSMC_PCCARDInitStructure);

Timing.FSMC_SetupTime     = 0x04;
Timing.FSMC_WaitSetupTime = 0x06;
Timing.FSMC_HoldSetupTime = 0x04;
Timing.FSMC_HiZSetupTime  = 0x02;

FSMC_PCCARDInitStructure.FSMC_CommonSpaceTimingStruct    = &Timing;
FSMC_PCCARDInitStructure.FSMC_AttributeSpaceTimingStruct = &Timing;
FSMC_PCCARDInitStructure.FSMC_IOSpaceTimingStruct        = &Timing;
FSMC_PCCARDInit(&FSMC_PCCARDInitStructure);

FSMC_NORSRAMInit(&FSMC_NORSRAMInitStructure);
FSMC_NORSRAMCmd(FSMC_Bank1_NORSRAM3, ENABLE);   /* 别漏，否则 Bank 不工作 */

/* 低功耗：外部 SRAM 断电前先关掉这个 Bank */
FSMC_NORSRAMCmd(FSMC_Bank1_NORSRAM3, DISABLE);

FSMC_NANDInit(&FSMC_NANDInitStructure);
FSMC_NANDCmd(FSMC_Bank2_NAND, ENABLE);

/* 使能后即可以 0x70000000 为基址访问 NAND */

/* 方式一：在 FSMC_NANDInit 里用 FSMC_ECC_Enable 一起配好 */
/* 方式二：单独开关 */
FSMC_NANDECCCmd(FSMC_Bank2_NAND, ENABLE);

/* 读完一整页后立刻取走 ECC 结果 */
while (FSMC_GetFlagStatus(FSMC_Bank2_NAND, FSMC_FLAG_FEMPT) == SET) { }
uint32_t ecc = FSMC_GetECC(FSMC_Bank2_NAND);

uint32_t eccRead, eccCalc;

/* 1. 触发一次整页读（以 0x70000000 为基址的 NAND 读页命令序列） */
NAND_ReadPage(block, page);   /* 用户自己实现 */

/* 2. 等 ECC 计算完成（FIFO 空标志） */
while (FSMC_GetFlagStatus(FSMC_Bank2_NAND, FSMC_FLAG_FEMPT) == SET) { }

/* 3. 取硬件 ECC 并与软件算出的期望值比对 */
eccRead = FSMC_GetECC(FSMC_Bank2_NAND);
eccCalc = NAND_CalcECC(pageBuf, 2048);
if (eccRead != eccCalc)
{
  /* 校验失败：判坏块或重读 */
}

NVIC_InitTypeDef NVIC_InitStructure;

/* 1. 使能 R/B 上升沿中断 */
FSMC_ITConfig(FSMC_Bank2_NAND, FSMC_IT_RisingEdge, ENABLE);

/* 2. 别忘了 NVIC，否则中断永远不会进 */
NVIC_InitStructure.NVIC_IRQChannel = FSMC_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x00;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

/* 3. 中断服务函数里必须清挂起位 */
void FSMC_IRQHandler(void)
{
  if (FSMC_GetITStatus(FSMC_Bank2_NAND, FSMC_IT_RisingEdge) != RESET)
  {
    FSMC_ClearITPendingBit(FSMC_Bank2_NAND, FSMC_IT_RisingEdge);
  }
}

/* 轮询等待 NAND 操作完成（不用中断的写法） */
void NAND_WaitReady(void)
{
  uint32_t t = 0;
  /* 等 R/B 回到高电平 */
  while (FSMC_GetFlagStatus(FSMC_Bank2_NAND, FSMC_FLAG_Level) == RESET)
  {
    if (++t > 1000000u) { break; }   /* 一定要有超时，否则会死等 */
  }
  FSMC_ClearFlag(FSMC_Bank2_NAND, FSMC_FLAG_RisingEdge | FSMC_FLAG_FallingEdge);
}

/* 等 ECC 计算结束再取值 */
while (FSMC_GetFlagStatus(FSMC_Bank2_NAND, FSMC_FLAG_FEMPT) == SET) { }

/* 等待 R/B 上升沿事件后清标志 */
while (FSMC_GetFlagStatus(FSMC_Bank2_NAND, FSMC_FLAG_RisingEdge) == RESET) { }

/* 业务处理 */
NAND_ReadPageDone();

/* 清掉本次事件标志，防止下次误判 */
FSMC_ClearFlag(FSMC_Bank2_NAND, FSMC_FLAG_RisingEdge);

void FSMC_IRQHandler(void)
{
  /* 判断具体是哪个中断源触发 */
  if (FSMC_GetITStatus(FSMC_Bank2_NAND, FSMC_IT_RisingEdge) != RESET)
  {
    FSMC_ClearITPendingBit(FSMC_Bank2_NAND, FSMC_IT_RisingEdge);
    /* R/B 变高：NAND 空闲，可以去读数据了 */
  }
}

void FSMC_IRQHandler(void)
{
  if (FSMC_GetITStatus(FSMC_Bank2_NAND, FSMC_IT_RisingEdge) != RESET)
  {
    /* 先处理业务，再清挂起位 */
    NAND_OnReady();
    FSMC_ClearITPendingBit(FSMC_Bank2_NAND, FSMC_IT_RisingEdge);
  }
}
